import subprocess, sys, socket, time, urllib.request, threading
p = subprocess.Popen([sys.executable, "server.py"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
try:
    deadline = time.time() + 6
    while True:
        try:
            socket.create_connection(("127.0.0.1", 8000), timeout=0.5).close(); break
        except OSError:
            if time.time() > deadline or p.poll() is not None: raise SystemExit("server did not start on 8000")
            time.sleep(0.1)
    assert urllib.request.urlopen("http://127.0.0.1:8000/", timeout=3).status == 200
    idle = [socket.create_connection(("127.0.0.1", 8000), timeout=2) for _ in range(3)]
    for s in idle: s.sendall(b"GET / HTTP/1.1\r\n")  # incomplete request, keeps a handler busy
    time.sleep(0.2)
    res = []
    def get():
        try: res.append(urllib.request.urlopen("http://127.0.0.1:8000/", timeout=4).status)
        except Exception as e: res.append(repr(e))
    ts = [threading.Thread(target=get) for _ in range(5)]
    [t.start() for t in ts]; [t.join() for t in ts]
    assert res == [200]*5, res
    for s in idle: s.close()
finally:
    p.kill(); p.wait()
print("ok")
